package com.skyreserve.controller; import com.skyreserve.service.UserService; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller public class AuthController {private final UserService users; public AuthController(UserService u){users=u;} @GetMapping("/register") String register(){return "register";} @PostMapping("/register") String doRegister(@RequestParam String name,@RequestParam String email,@RequestParam String password,@RequestParam String phone,Model m){try{users.register(name,email,password,phone);return "redirect:/login?registered";}catch(Exception e){m.addAttribute("error",e.getMessage());return "register";}} @GetMapping("/dashboard") String dash(){return "dashboard";} }